-- Actualizacion aditiva para Gestor Documental SoyAsesorias.
-- Selecciona primero la base de datos de produccion.
-- No elimina ni modifica documentos, usuarios, empresas ni solicitudes existentes.
-- Los cambios de esquema y los datos del catalogo son idempotentes.
SET NAMES utf8mb4;
SET @schema_name = DATABASE();

-- Permiso por usuario y perfil de acceso especializado.
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='user_modulos' AND COLUMN_NAME='gestor_documental')=0, 'ALTER TABLE `user_modulos` ADD COLUMN `gestor_documental` TINYINT(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='users' AND COLUMN_NAME='perfil_acceso')=0, 'ALTER TABLE `users` ADD COLUMN `perfil_acceso` VARCHAR(30) NULL', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
CREATE TABLE IF NOT EXISTS `user_modulo_permisos` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `user_id` INT UNSIGNED NOT NULL,
  `modulo` VARCHAR(80) NOT NULL,
  `habilitado` TINYINT(1) NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_modulo_permisos_user_modulo_unique` (`user_id`, `modulo`),
  KEY `user_modulo_permisos_user_id_index` (`user_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Usuarios secundarios de empresa; no reemplaza empresas.user_id.
CREATE TABLE IF NOT EXISTS `empresa_usuarios` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `empresa_id` INT UNSIGNED NOT NULL,
  `user_id` INT UNSIGNED NOT NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `empresa_usuarios_user_id_unique` (`user_id`),
  UNIQUE KEY `empresa_usuarios_empresa_user_unique` (`empresa_id`, `user_id`),
  KEY `empresa_usuarios_empresa_id_index` (`empresa_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Carpetas del gestor anterior y metadatos en documentos.
CREATE TABLE IF NOT EXISTS `gestor_documental_carpetas` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `empresa_id` INT UNSIGNED NOT NULL,
  `parent_id` INT UNSIGNED NULL,
  `nombre` VARCHAR(120) NOT NULL,
  `created_by` INT UNSIGNED NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `gestor_documental_carpetas_empresa_id_index` (`empresa_id`),
  KEY `gestor_documental_carpetas_parent_id_index` (`parent_id`),
  KEY `gestor_documental_carpetas_created_by_foreign` (`created_by`),
  KEY `gdc_empresa_parent_idx` (`empresa_id`, `parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='documentos' AND COLUMN_NAME='gestor_carpeta_id')=0, 'ALTER TABLE `documentos` ADD COLUMN `gestor_carpeta_id` INT UNSIGNED NULL', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='documentos' AND INDEX_NAME='documentos_gestor_carpeta_id_index')=0, 'CREATE INDEX `documentos_gestor_carpeta_id_index` ON `documentos` (`gestor_carpeta_id`)', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='documentos' AND COLUMN_NAME='es_gestor_documental')=0, 'ALTER TABLE `documentos` ADD COLUMN `es_gestor_documental` TINYINT(1) NOT NULL DEFAULT 0', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='documentos' AND INDEX_NAME='documentos_es_gestor_documental_index')=0, 'CREATE INDEX `documentos_es_gestor_documental_index` ON `documentos` (`es_gestor_documental`)', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;

-- Categorias y subcategorias importadas del Excel.
CREATE TABLE IF NOT EXISTS `gestor_documental_categorias` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `codigo` VARCHAR(180) NOT NULL,
  `numero` VARCHAR(20) NULL,
  `parent_id` INT UNSIGNED NULL,
  `nombre` VARCHAR(255) NOT NULL,
  `orden` INT NOT NULL DEFAULT 0,
  `activo` TINYINT(1) NOT NULL DEFAULT 1,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `gestor_documental_categorias_codigo_unique` (`codigo`),
  KEY `gestor_documental_categorias_parent_id_index` (`parent_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Catalogo de modelos generales y borradores del administrador.
CREATE TABLE IF NOT EXISTS `gestor_documental_catalogo` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `source_code` VARCHAR(40) NOT NULL,
  `categoria_id` INT UNSIGNED NOT NULL,
  `nombre` VARCHAR(255) NOT NULL,
  `orden` INT NOT NULL DEFAULT 0,
  `activo` TINYINT(1) NOT NULL DEFAULT 1,
  `borrador_path` VARCHAR(500) NULL,
  `borrador_nombre` VARCHAR(255) NULL,
  `borrador_mime` VARCHAR(100) NULL,
  `borrador_size` INT UNSIGNED NULL,
  `borrador_publicado` TINYINT(1) NOT NULL DEFAULT 0,
  `actualizado_por` INT UNSIGNED NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `gestor_documental_catalogo_source_code_unique` (`source_code`),
  KEY `gestor_documental_catalogo_categoria_id_index` (`categoria_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Archivos finales cargados por cada empresa.
CREATE TABLE IF NOT EXISTS `gestor_documental_archivos` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `empresa_id` INT UNSIGNED NOT NULL,
  `catalogo_id` INT UNSIGNED NOT NULL,
  `uploaded_by` INT UNSIGNED NULL,
  `nombre` VARCHAR(255) NOT NULL,
  `path` VARCHAR(500) NOT NULL,
  `mime` VARCHAR(100) NULL,
  `size` INT UNSIGNED NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `gestor_documental_archivos_empresa_id_index` (`empresa_id`),
  KEY `gestor_documental_archivos_catalogo_id_index` (`catalogo_id`),
  KEY `gda_empresa_catalogo_id_idx` (`empresa_id`, `catalogo_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Snapshot de los documentos solicitados en paquetes o solicitudes individuales.
CREATE TABLE IF NOT EXISTS `gestor_documental_solicitud_items` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `solicitud_id` INT UNSIGNED NOT NULL,
  `catalogo_id` INT UNSIGNED NOT NULL,
  `categoria_id` INT UNSIGNED NOT NULL,
  `nombre` VARCHAR(255) NOT NULL,
  `orden` INT NOT NULL DEFAULT 0,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `gds_items_solicitud_catalogo_unique` (`solicitud_id`, `catalogo_id`),
  KEY `gestor_documental_solicitud_items_solicitud_id_index` (`solicitud_id`),
  KEY `gestor_documental_solicitud_items_catalogo_id_index` (`catalogo_id`),
  KEY `gestor_documental_solicitud_items_categoria_id_index` (`categoria_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Entregas del administrador por documento solicitado; conserva historial.
CREATE TABLE IF NOT EXISTS `gestor_documental_entregas` (
  `id` INT UNSIGNED NOT NULL AUTO_INCREMENT,
  `solicitud_id` INT UNSIGNED NOT NULL,
  `solicitud_item_id` INT UNSIGNED NOT NULL,
  `catalogo_id` INT UNSIGNED NOT NULL,
  `empresa_id` INT UNSIGNED NOT NULL,
  `uploaded_by` INT UNSIGNED NULL,
  `nombre` VARCHAR(255) NOT NULL,
  `path` VARCHAR(500) NOT NULL,
  `mime` VARCHAR(100) NULL,
  `size` INT UNSIGNED NULL,
  `created_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `updated_at` TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  KEY `gestor_documental_entregas_solicitud_id_index` (`solicitud_id`),
  KEY `gestor_documental_entregas_solicitud_item_id_index` (`solicitud_item_id`),
  KEY `gestor_documental_entregas_catalogo_id_index` (`catalogo_id`),
  KEY `gestor_documental_entregas_empresa_id_index` (`empresa_id`),
  KEY `gde_solicitud_catalogo_id_idx` (`solicitud_id`, `catalogo_id`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- Relacion de solicitudes del modulo.
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='solicitudes' AND COLUMN_NAME='gestor_categoria_id')=0, 'ALTER TABLE `solicitudes` ADD COLUMN `gestor_categoria_id` INT UNSIGNED NULL', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='solicitudes' AND COLUMN_NAME='gestor_catalogo_id')=0, 'ALTER TABLE `solicitudes` ADD COLUMN `gestor_catalogo_id` INT UNSIGNED NULL', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='solicitudes' AND COLUMN_NAME='solicitado_por')=0, 'ALTER TABLE `solicitudes` ADD COLUMN `solicitado_por` INT UNSIGNED NULL', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='solicitudes' AND INDEX_NAME='solicitudes_gestor_categoria_id_index')=0, 'CREATE INDEX `solicitudes_gestor_categoria_id_index` ON `solicitudes` (`gestor_categoria_id`)', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='solicitudes' AND INDEX_NAME='solicitudes_gestor_catalogo_id_index')=0, 'CREATE INDEX `solicitudes_gestor_catalogo_id_index` ON `solicitudes` (`gestor_catalogo_id`)', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;
SET @sql = IF((SELECT COUNT(*) FROM information_schema.STATISTICS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='solicitudes' AND INDEX_NAME='solicitudes_solicitado_por_index')=0, 'CREATE INDEX `solicitudes_solicitado_por_index` ON `solicitudes` (`solicitado_por`)', 'SELECT 1');
PREPARE gestor_ddl FROM @sql; EXECUTE gestor_ddl; DEALLOCATE PREPARE gestor_ddl;

-- Inserta categorias que falten sin sobrescribir cambios del administrador.

-- Backfill de solicitudes Gestor existentes: captura el contenido solicitado.
SELECT s.id,d.id,d.categoria_id,d.nombre,1,NOW(),NOW()
FROM `solicitudes` s JOIN `gestor_documental_catalogo` d ON d.id=s.gestor_catalogo_id
WHERE s.tipo_solicitud='gestor_documento' AND s.gestor_catalogo_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `gestor_documental_solicitud_items` i WHERE i.solicitud_id=s.id AND i.catalogo_id=d.id);
SELECT s.id,d.id,d.categoria_id,d.nombre,d.orden,NOW(),NOW()
FROM `solicitudes` s
JOIN `gestor_documental_categorias` c ON c.id=s.gestor_categoria_id OR c.parent_id=s.gestor_categoria_id
JOIN `gestor_documental_catalogo` d ON d.categoria_id=c.id
WHERE s.tipo_solicitud='gestor_paquete' AND s.gestor_categoria_id IS NOT NULL
  AND NOT EXISTS (SELECT 1 FROM `gestor_documental_solicitud_items` i WHERE i.solicitud_id=s.id AND i.catalogo_id=d.id);

-- Normaliza dos subcategorias que el Excel numeraba ambas como 5.5.
UPDATE `gestor_documental_categorias` SET `numero`='5.6' WHERE `codigo`='5.5-gestion-de-turno-y-horarios-laborales' AND `numero`='5.5';
UPDATE `gestor_documental_categorias` SET `numero`='5.7' WHERE `codigo`='5.5-gestion-documental-del-proceso' AND `numero`='5.5';

-- Verificacion: 24 categorias/subcategorias y 250 documentos base.
SELECT COUNT(*) AS categorias_y_subcategorias FROM `gestor_documental_categorias`;
SELECT COUNT(*) AS documentos_catalogo FROM `gestor_documental_catalogo`;
SELECT `numero`,`nombre` FROM `gestor_documental_categorias` WHERE `parent_id`=(SELECT `id` FROM `gestor_documental_categorias` WHERE `codigo`='5' LIMIT 1) ORDER BY `orden`;
